from scipy.sparse.csgraph import minimum_spanning_tree

def thin(bw):
 p=np.pad(bw,1)
 while True:
  changed=0
  for sub in (0,1):
   a=p[1:-1,1:-1]
   n=[p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]]
   B=sum(x.astype(np.uint8) for x in n);A=sum((~n[i]&n[(i+1)%8]).astype(np.uint8) for i in range(8))
   r=a&(B>=2)&(B<=6)&(A==1)
   if sub==0:r&=~(n[0]&n[2]&n[4])&~(n[2]&n[4]&n[6])
   else:r&=~(n[0]&n[2]&n[6])&~(n[0]&n[4]&n[6])
   changed+=int(r.sum());p[1:-1,1:-1][r]=False
  if not changed:break
 return p[1:-1,1:-1]

