  mst=minimum_spanning_tree(csr_matrix((ww,(rr,cc)),shape=(N,N))).tocoo();adj=[[]for _ in range(N)]
  for i,j,w in zip(mst.row,mst.col,mst.data):adj[int(i)].append((int(j),float(w)));adj[int(j)].append((int(i),float(w)))
  if len(mst.data)!=N-1:raise ValueError((N,len(mst.data)))
